## Konkrét implementáció: Modal.com + B200:8 + Zig + Futhark LLM training

Igen, **pontosan ezt meg lehet csinálni** a Modal.com API-val. Íme a konkrét lépések és kód példák:

### Modal.com B200:8 GPU allokáció - Konkrét szintaxis

A Modal API-ban egyetlen dekorátor-sorral allokálhatod a B200:8 GPU-t:[1][2][3]

```python
import modal

app = modal.App("zig-futhark-llm-training")

@app.function(gpu="B200:8")
def train_llm():
    # Ez a függvény 8x B200 GPU-val fut
    pass
```

Ez **1536 GB GPU RAM-ot** ad neked (8x 192GB), és a Modal automatikusan provision-öli a hardware-t.[4][5]

### Egyedi Dockerfile Modal-ra - Teljes példa

Készítened kell egy Dockerfile-t, ami tartalmazza a Zig fordítót, Futhark fordítót és CUDA toolkit-et:[6][7][3]

**Dockerfile:**
```dockerfile
FROM nvidia/cuda:12.4.0-devel-ubuntu22.04

# Python hozzáadása (Modal requirement)
RUN apt-get update && apt-get install -y python3.11 python3-pip wget curl

# Zig compiler telepítése (latest)
RUN wget  \
    && tar -xf zig-linux-x86_64-0.13.0.tar.xz \
    && mv zig-linux-x86_64-0.13.0 /opt/zig \
    && ln -s /opt/zig/zig /usr/local/bin/zig

# Futhark compiler telepítése
RUN wget  \
    && tar -xf futhark-0.25.34-linux-x86_64.tar.xz \
    && mv futhark-0.25.34-linux-x86_64/bin/futhark /usr/local/bin/ \
    && chmod +x /usr/local/bin/futhark

# CUDA headers elérhetővé tétele
ENV CUDA_HOME=/usr/local/cuda
ENV PATH=$PATH:/usr/local/cuda/bin
ENV LD_LIBRARY_PATH=$LD_LIBRARY_PATH:/usr/local/cuda/lib64

# Working directory
WORKDIR /app
COPY . /app
```

**Modal Python script (train.py):**
```python
import modal
import subprocess

# Egyedi image build Dockerfile-ból
custom_image = modal.Image.from_dockerfile("Dockerfile")

app = modal.App("zig-futhark-llm")

@app.function(
    gpu="B200:8",
    image=custom_image,
    timeout=86400,  # 24 óra
    cpu=64,
    memory=512000  # 512GB RAM
)
def build_and_train():
    """
    Build Zig+Futhark kód és training futtatás
    """
    # 1. Futhark GPU kernels fordítása
    subprocess.run([
        "futhark", "cuda", 
        "--library",
        "-o", "gpu_kernels",
        "kernels.fut"
    ], check=True)

    # 2. Zig projekt build (linkeli a Futhark C library-t)
    subprocess.run([
        "zig", "build", 
        "-Doptimize=ReleaseFast",
        "-Dtarget=x86_64-linux-gnu"
    ], check=True)

    # 3. Training futtatás
    result = subprocess.run([
        "./zig-out/bin/llm_trainer",
        "--gpus=8",
        "--model-config=config.json",
        "--data-path=/data/training_set"
    ], check=True, capture_output=True)

    return result.stdout.decode()

@app.local_entrypoint()
def main():
    # Local gépről indítás, távoli B200:8 GPU-n futtatás
    result = build_and_train.remote()
    print(result)
```

Futtatás:
```bash
modal run train.py
```

### Futhark CUDA library generálás - Konkrét parancs

A Futhark fordító `--library` flag-gel C API-t generál, amit Zig-ből hívhatsz:[8][9]

**kernels.fut** (példa GPU kernels):
```futhark
-- Matrix multiplication kernel
def matmul [n][m][p] (A: [n][m]f32) (B: [m][p]f32) : [n][p]f32 =
  map (\row -> 
    map (\col -> 
      f32.sum (map2 (*) row col)
    ) (transpose B)
  ) A

-- Softmax kernel
def softmax [n] (xs: [n]f32) : [n]f32 =
  let max_val = f32.maximum xs
  let exps = map (\x -> f32.exp(x - max_val)) xs
  let sum_exps = f32.sum exps
  in map (\e -> e / sum_exps) exps

-- Attention score calculation
def attention_scores [seq_len][d_model] 
                     (Q: [seq_len][d_model]f32) 
                     (K: [seq_len][d_model]f32) 
                     : [seq_len][seq_len]f32 =
  let scale = f32.sqrt (f32.i64 d_model)
  let scores = matmul Q (transpose K)
  in map (\row -> map (\x -> x / scale) row) scores

-- Entry point for training step
entry train_step [batch][seq][vocab] 
                 (input_ids: [batch][seq]i32)
                 (embeddings: [vocab][512]f32)
                 (weights_qkv: [512][1536]f32)
                 : ([batch][seq][vocab]f32, f32) =
  -- Training step implementation
  -- Returns (logits, loss)
  ...
```

Fordítás CUDA library-vá:
```bash
futhark cuda --library -o gpu_kernels kernels.fut
```

Ez generálja:
- `gpu_kernels.h` - C header file
- `gpu_kernels.c` - C implementation CUDA kernelekkel

### Zig FFI: Futhark C library használata

A Zig `@cImport` beépített funkcióval importálhatod a Futhark-generated C API-t:[10][11]

**build.zig:**
```zig
const std = @import("std");

pub fn build(b: *std.Build) void {
    const target = b.standardTargetOptions(.{});
    const optimize = b.standardOptimizeOption(.{});

    const exe = b.addExecutable(.{
        .name = "llm_trainer",
        .root_source_file = b.path("src/main.zig"),
        .target = target,
        .optimize = optimize,
    });

    // Link C library (Futhark generated)
    exe.linkLibC();

    // Add Futhark library sources
    exe.addCSourceFile(.{
        .file = b.path("gpu_kernels.c"),
        .flags = &[_][]const u8{
            "-O3",
            "-march=native",
        },
    });

    // CUDA library linking
    exe.addLibraryPath(.{ .path = "/usr/local/cuda/lib64" });
    exe.linkSystemLibrary("cuda");
    exe.linkSystemLibrary("cudart");
    exe.linkSystemLibrary("nvrtc");

    // Include paths
    exe.addIncludePath(.{ .path = "." });
    exe.addIncludePath(.{ .path = "/usr/local/cuda/include" });

    b.installArtifact(exe);
}
```

**src/main.zig:**
```zig
const std = @import("std");
const c = @cImport({
    @cInclude("gpu_kernels.h");
});

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    // Futhark context létrehozása
    var cfg = c.futhark_context_config_new();
    defer c.futhark_context_config_free(cfg);

    // Multi-GPU setup (8x B200)
    c.futhark_context_config_set_device(cfg, 0);

    var ctx = c.futhark_context_new(cfg);
    defer c.futhark_context_free(ctx);

    // Model paraméterek allokálása GPU-n
    const vocab_size: i64 = 50257;
    const d_model: i64 = 4096;
    const n_layers: i64 = 32;
    const batch_size: i64 = 8;
    const seq_len: i64 = 2048;

    std.debug.print("Initializing LLM training on 8x NVIDIA B200...\n", .{});

    // Embedding matrix allokáció
    var embeddings_data = try allocator.alloc(f32, @intCast(vocab_size * d_model));
    defer allocator.free(embeddings_data);

    // Random init
    var prng = std.rand.DefaultPrng.init(42);
    const random = prng.random();
    for (embeddings_data) |*val| {
        val.* = random.floatNorm(f32);
    }

    // GPU array létrehozás (Futhark API)
    var embeddings_gpu = c.futhark_new_f32_2d(
        ctx, 
        embeddings_data.ptr, 
        vocab_size, 
        d_model
    );
    defer c.futhark_free_f32_2d(ctx, embeddings_gpu);

    // QKV weight matrices
    var weights_qkv_data = try allocator.alloc(f32, @intCast(d_model * d_model * 3));
    defer allocator.free(weights_qkv_data);

    for (weights_qkv_data) |*val| {
        val.* = random.floatNorm(f32) * 0.02;
    }

    var weights_qkv_gpu = c.futhark_new_f32_2d(
        ctx,
        weights_qkv_data.ptr,
        d_model,
        d_model * 3
    );
    defer c.futhark_free_f32_2d(ctx, weights_qkv_gpu);

    // Training loop
    const num_epochs: usize = 10;
    const num_steps: usize = 100000;

    var epoch: usize = 0;
    while (epoch < num_epochs) : (epoch += 1) {
        std.debug.print("Epoch {}/{}\n", .{epoch + 1, num_epochs});

        var step: usize = 0;
        while (step < num_steps) : (step += 1) {
            // Batch data betöltése (mock data)
            var input_ids = try allocator.alloc(i32, @intCast(batch_size * seq_len));
            defer allocator.free(input_ids);

            for (input_ids) |*id| {
                id.* = @intCast(random.intRangeAtMost(u32, 0, @intCast(vocab_size - 1)));
            }

            var input_ids_gpu = c.futhark_new_i32_2d(
                ctx,
                input_ids.ptr,
                batch_size,
                seq_len
            );
            defer c.futhark_free_i32_2d(ctx, input_ids_gpu);

            // Forward pass - Futhark entry point hívás
            var logits_gpu: ?*c.futhark_f32_3d = null;
            var loss: f32 = 0.0;

            const err = c.futhark_entry_train_step(
                ctx,
                &logits_gpu,
                &loss,
                input_ids_gpu,
                embeddings_gpu,
                weights_qkv_gpu
            );

            if (err != 0) {
                std.debug.print("Futhark error: {s}\n", .{c.futhark_context_get_error(ctx)});
                return error.FutharkError;
            }

            defer c.futhark_free_f32_3d(ctx, logits_gpu);

            // Backward pass és optimizer step
            // (további Futhark kernelekkel implementálva)

            if (step % 100 == 0) {
                std.debug.print("Step {}: Loss = {d:.6}\n", .{step, loss});
            }

            // Checkpoint mentés
            if (step % 10000 == 0) {
                try saveCheckpoint(allocator, ctx, embeddings_gpu, weights_qkv_gpu, step);
            }
        }
    }

    std.debug.print("Training completed!\n", .{});
}

fn saveCheckpoint(
    allocator: std.mem.Allocator,
    ctx: ?*c.futhark_context,
    embeddings: ?*c.futhark_f32_2d,
    weights: ?*c.futhark_f32_2d,
    step: usize
) !void {
    // GPU -> CPU transfer
    var shape: [2]i64 = undefined;
    _ = c.futhark_shape_f32_2d(ctx, embeddings, &shape);

    const total_size = shape[0] * shape[1];
    var cpu_data = try allocator.alloc(f32, @intCast(total_size));
    defer allocator.free(cpu_data);

    _ = c.futhark_values_f32_2d(ctx, embeddings, cpu_data.ptr);

    // File írás
    const filename = try std.fmt.allocPrint(
        allocator, 
        "checkpoint_step_{}.bin", 
        .{step}
    );
    defer allocator.free(filename);

    const file = try std.fs.cwd().createFile(filename, .{});
    defer file.close();

    const bytes = std.mem.sliceAsBytes(cpu_data);
    try file.writeAll(bytes);

    std.debug.print("Checkpoint saved: {s}\n", .{filename});
}
```

### Zig CUDA kernel írás (opcionális - direct CUDA)

Ha a Futhark mellett direkt CUDA kernelt is akarsz írni Zig-ből:[12][13]

**src/cuda_kernels.zig:**
```zig
const std = @import("std");
const cuda = @cImport({
    @cInclude("cuda_runtime.h");
    @cInclude("cuda.h");
});

pub const CudaContext = struct {
    device: c_int,
    stream: cuda.cudaStream_t,

    pub fn init(device_id: c_int) !CudaContext {
        var stream: cuda.cudaStream_t = undefined;

        if (cuda.cudaSetDevice(device_id) != cuda.cudaSuccess) {
            return error.CudaDeviceSetFailed;
        }

        if (cuda.cudaStreamCreate(&stream) != cuda.cudaSuccess) {
            return error.CudaStreamCreateFailed;
        }

        return CudaContext{
            .device = device_id,
            .stream = stream,
        };
    }

    pub fn deinit(self: *CudaContext) void {
        _ = cuda.cudaStreamDestroy(self.stream);
    }

    pub fn allocDeviceMem(self: *CudaContext, comptime T: type, count: usize) ![]T {
        var dev_ptr: ?*anyopaque = null;
        const size = @sizeOf(T) * count;

        if (cuda.cudaMalloc(&dev_ptr, size) != cuda.cudaSuccess) {
            return error.CudaAllocFailed;
        }

        return @as([*]T, @ptrCast(@alignCast(dev_ptr)))[0..count];
    }

    pub fn freeDeviceMem(self: *CudaContext, ptr: anytype) void {
        _ = self;
        _ = cuda.cudaFree(@ptrCast(ptr.ptr));
    }

    pub fn copyHostToDevice(self: *CudaContext, comptime T: type, dst: []T, src: []const T) !void {
        const size = @sizeOf(T) * src.len;

        if (cuda.cudaMemcpyAsync(
            @ptrCast(dst.ptr),
            @ptrCast(src.ptr),
            size,
            cuda.cudaMemcpyHostToDevice,
            self.stream
        ) != cuda.cudaSuccess) {
            return error.CudaCopyFailed;
        }

        _ = cuda.cudaStreamSynchronize(self.stream);
    }

    pub fn copyDeviceToHost(self: *CudaContext, comptime T: type, dst: []T, src: []const T) !void {
        const size = @sizeOf(T) * src.len;

        if (cuda.cudaMemcpyAsync(
            @ptrCast(dst.ptr),
            @ptrCast(src.ptr),
            size,
            cuda.cudaMemcpyDeviceToHost,
            self.stream
        ) != cuda.cudaSuccess) {
            return error.CudaCopyFailed;
        }

        _ = cuda.cudaStreamSynchronize(self.stream);
    }
};

// PTX kernel string (inline assembly vagy külső file-ból)
const elementwise_kernel_ptx = 
    \\.version 7.0
    \\.target sm_80
    \\.address_size 64
    \\
    \\.visible .entry elementwise_add(
    \\    .param .u64 out,
    \\    .param .u64 in1,
    \\    .param .u64 in2,
    \\    .param .u32 n
    \\) {
    \\    .reg .u32 %tid;
    \\    .reg .u64 %r<6>;
    \\    .reg .f32 %f<3>;
    \\    
    \\    mov.u32 %tid, %tid.x;
    \\    ld.param.u64 %r1, [out];
    \\    ld.param.u64 %r2, [in1];
    \\    ld.param.u64 %r3, [in2];
    \\    ld.param.u32 %r4, [n];
    \\    
    \\    setp.ge.u32 %p1, %tid, %r4;
    \\    @%p1 bra done;
    \\    
    \\    mul.wide.u32 %r5, %tid, 4;
    \\    add.u64 %r2, %r2, %r5;
    \\    add.u64 %r3, %r3, %r5;
    \\    add.u64 %r1, %r1, %r5;
    \\    
    \\    ld.global.f32 %f1, [%r2];
    \\    ld.global.f32 %f2, [%r3];
    \\    add.f32 %f3, %f1, %f2;
    \\    st.global.f32 [%r1], %f3;
    \\    
    \\done:
    \\    ret;
    \\}
;

pub fn launchElementwiseAdd(
    ctx: *CudaContext,
    out: []f32,
    in1: []const f32,
    in2: []const f32
) !void {
    const n: u32 = @intCast(in1.len);
    const threads_per_block: u32 = 256;
    const num_blocks: u32 = (n + threads_per_block - 1) / threads_per_block;

    // Load PTX module
    var cumodule: cuda.CUmodule = undefined;
    var cufunction: cuda.CUfunction = undefined;

    if (cuda.cuModuleLoadData(&cumodule, elementwise_kernel_ptx.ptr) != cuda.CUDA_SUCCESS) {
        return error.CudaModuleLoadFailed;
    }
    defer _ = cuda.cuModuleUnload(cumodule);

    if (cuda.cuModuleGetFunction(&cufunction, cumodule, "elementwise_add") != cuda.CUDA_SUCCESS) {
        return error.CudaGetFunctionFailed;
    }

    // Kernel parameters
    var params = [_]?*const anyopaque{
        @ptrCast(&out.ptr),
        @ptrCast(&in1.ptr),
        @ptrCast(&in2.ptr),
        @ptrCast(&n),
    };

    // Launch kernel
    if (cuda.cuLaunchKernel(
        cufunction,
        num_blocks, 1, 1,  // grid dim
        threads_per_block, 1, 1,  // block dim
        0,  // shared mem
        ctx.stream,
        &params,
        null
    ) != cuda.CUDA_SUCCESS) {
        return error.CudaLaunchFailed;
    }

    _ = cuda.cudaStreamSynchronize(ctx.stream);
}
```

### Multi-GPU koordináció (8x B200)

**src/multi_gpu.zig:**
```zig
const std = @import("std");
const cuda = @import("cuda_kernels.zig");

pub const MultiGPUTrainer = struct {
    contexts: []cuda.CudaContext,
    allocator: std.mem.Allocator,
    num_gpus: usize,

    pub fn init(allocator: std.mem.Allocator, num_gpus: usize) !MultiGPUTrainer {
        var contexts = try allocator.alloc(cuda.CudaContext, num_gpus);
        errdefer allocator.free(contexts);

        for (0..num_gpus) |i| {
            contexts[i] = try cuda.CudaContext.init(@intCast(i));
        }

        return MultiGPUTrainer{
            .contexts = contexts,
            .allocator = allocator,
            .num_gpus = num_gpus,
        };
    }

    pub fn deinit(self: *MultiGPUTrainer) void {
        for (self.contexts) |*ctx| {
            ctx.deinit();
        }
        self.allocator.free(self.contexts);
    }

    pub fn distributeData(
        self: *MultiGPUTrainer,
        global_batch: []const f32,
        batch_size_per_gpu: usize
    ) !void {
        // Data parallelism: minden GPU kap egy batch szeletet
        var threads = try self.allocator.alloc(std.Thread, self.num_gpus);
        defer self.allocator.free(threads);

        for (0..self.num_gpus) |gpu_id| {
            const start = gpu_id * batch_size_per_gpu;
            const end = start + batch_size_per_gpu;
            const batch_slice = global_batch[start..end];

            threads[gpu_id] = try std.Thread.spawn(.{}, transferToGPU, .{
                &self.contexts[gpu_id],
                batch_slice,
            });
        }

        for (threads) |thread| {
            thread.join();
        }
    }

    fn transferToGPU(ctx: *cuda.CudaContext, data: []const f32) void {
        var dev_mem = ctx.allocDeviceMem(f32, data.len) catch return;
        defer ctx.freeDeviceMem(dev_mem);

        ctx.copyHostToDevice(f32, dev_mem, data) catch return;

        // Forward pass would happen here
    }

    pub fn allReduceGradients(self: *MultiGPUTrainer) !void {
        // NCCL-szerű gradient aggregation implementálható
        // Egyszerű verzió: CPU-n összegzés
        std.debug.print("Reducing gradients across {} GPUs\n", .{self.num_gpus});
    }
};
